import{_ as e,o,c as a,ah as r}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Certificate and Canopé","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/apprenant/certification.md","filePath":"src/en/guide/apprenant/certification.md"}'),n={name:"en/guide/apprenant/certification.md"};function i(s,t,c,d,l,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="certificate-and-canope" tabindex="-1">Certificate and Canopé <a class="header-anchor" href="#certificate-and-canope" aria-label="Permalink to &quot;Certificate and Canopé&quot;">​</a></h1><h2 id="the-four-conditions" tabindex="-1">The four conditions <a class="header-anchor" href="#the-four-conditions" aria-label="Permalink to &quot;The four conditions&quot;">​</a></h2><p>The <strong>NextBoxx certificate</strong> is issued when <strong>all four conditions</strong> are met. None compensates for another:</p><ol><li>your <strong>average</strong> is at least 10/20;</li><li><strong>no block</strong> is under 8/20;</li><li>your <strong>defence</strong> is validated by the jury;</li><li>the <strong>balance</strong> of the training is paid in full.</li></ol><p>The cohort&#39;s results page shows the Coordinator, for each learner, which one is missing. If you are stuck, they are the person to contact.</p><h2 id="issuance" tabindex="-1">Issuance <a class="header-anchor" href="#issuance" aria-label="Permalink to &quot;Issuance&quot;">​</a></h2><p>The Pedagogical Coordinator issues the certificate, <strong>only once</strong>, in the name of the jury president. The document is a <strong>sealed</strong> PDF, which can no longer be modified.</p><p>It carries a <strong>mention</strong> on the French scale:</p><table tabindex="0"><thead><tr><th>Mention</th><th>From</th></tr></thead><tbody><tr><td>Passable</td><td>10/20</td></tr><tr><td>Assez bien</td><td>12/20</td></tr><tr><td>Bien</td><td>14/20</td></tr><tr><td>Très bien</td><td>16/20</td></tr></tbody></table><p>These thresholds are the defaults; the Administrator can adjust them.</p><p>At the same time you receive a <strong>transcript of competencies</strong>, which details the grades by block and the retakes, the tutored project, the internship and its company, and the average. It has no value on its own. Certificate (<code>CERT-NB-YYYY-XXX</code>) and transcript (<code>REL-NB-YYYY-XXX</code>) are in <strong>My enrolment</strong> and <strong>My documents</strong>.</p><h2 id="becoming-canope" tabindex="-1">Becoming Canopé <a class="header-anchor" href="#becoming-canope" aria-label="Permalink to &quot;Becoming Canopé&quot;">​</a></h2><p>Issuing the certificate ends your enrolment and opens the <strong>Canopé Journey</strong>:</p><ul><li>your enrolment becomes &quot;Completed&quot;;</li><li>you leave your cohort&#39;s course in Sève, as access to active courses is withdrawn;</li><li>your account moves to the <strong>Canopé</strong> state, which Sève reflects: you keep access to the <strong>community</strong>, <strong>mentoring</strong> and the <strong>portfolio</strong>, with no time limit.</li></ul><p>As a Canopé, you can also ask to become a Coach-Tutor (see <a href="./../premiers-pas.html#ask-for-a-role">Ask for a role</a>) or apply to <strong>L&#39;Éclosion</strong>, NextBoxx&#39;s incubation program, from <strong>Activities → My L&#39;Éclosion project</strong>.</p><h2 id="being-visible-to-companies" tabindex="-1">Being visible to companies <a class="header-anchor" href="#being-visible-to-companies" aria-label="Permalink to &quot;Being visible to companies&quot;">​</a></h2><p>Once certified, you can make yourself visible to companies that are recruiting. It is <strong>your choice</strong>, and it can be undone at any time. In <strong>Settings → Profile for companies</strong>:</p><ol><li>write a short <strong>presentation</strong> of what you look for and what you bring;</li><li>add your <strong>CV</strong> (PDF, 5 MB at most), required to be visible;</li><li>tick <strong>Be visible to companies</strong>.</li></ol><p>A company first sees your first name, your certificates and your presentation. Your contact details and CV are only shared with it if it retains your profile. If you hide your profile, it leaves the pending proposals; those already retained stay shared.</p><h2 id="if-you-drop-out" tabindex="-1">If you drop out <a class="header-anchor" href="#if-you-drop-out" aria-label="Permalink to &quot;If you drop out&quot;">​</a></h2><p>A drop-out, whether voluntary or pronounced after several non-payments, ends your enrolment. <strong>There is never a partial certificate.</strong></p><p>If you have validated <strong>at least one block</strong>, the Coordinator can issue you a <strong>partial attestation</strong>. It lists the validated blocks, those that were not validated or not followed, and the reason for the interruption. It comes with the transcript of competencies.</p><p>If you resume later, the balance is recalculated on the remaining blocks.</p><h2 id="how-long-your-documents-are-kept" tabindex="-1">How long your documents are kept <a class="header-anchor" href="#how-long-your-documents-are-kept" aria-label="Permalink to &quot;How long your documents are kept&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Document</th><th>Duration</th></tr></thead><tbody><tr><td>Certificates, partial attestations</td><td>No limit</td></tr><tr><td>Agreements, invoices, credit notes</td><td>10 years</td></tr><tr><td>Refused candidature</td><td>12 months, then anonymization</td></tr><tr><td>Inactive account</td><td>Deactivated after a year without sign-in, data kept</td></tr></tbody></table>',25)])])}const g=e(n,[["render",i]]);export{p as __pageData,g as default};
